"use client";

import * as React from "react";
import {
  Badge,
  Card,
  CardContent,
  Container,
  DocNote,
  EmptyState,
  ListCard,
  MetadataList,
  PageHeader,
  SegmentedControl,
  Skeleton,
  Spinner,
  StatGroup,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
  formatCurrency,
} from "@gunjo/ui";
import {
  IconCircleCheck,
  IconFileDescription,
  IconShieldCheck,
} from "@tabler/icons-react";
import { ClaimTab } from "./ClaimTab";
import { CoverageTab } from "./CoverageTab";
import { PremiumTab } from "./PremiumTab";
import { ProceduresTab } from "./ProceduresTab";
import { INSURED, POLICIES, formatJaDate, type Policy } from "./data";

type DemoState = "ready" | "loading" | "empty";

export default function PolicyPortalPage() {
  const [demoState, setDemoState] = React.useState<DemoState>("ready");
  const [openPolicyId, setOpenPolicyId] = React.useState<string | null>(null);

  const policies = demoState === "empty" ? [] : POLICIES;
  const openPolicy =
    policies.find((policy) => policy.id === openPolicyId) ?? null;

  const headingRef = React.useRef<HTMLDivElement>(null);
  const isFirstRender = React.useRef(true);

  // 一覧⇄詳細を行き来したとき、新しい見出しへフォーカスを移す。
  // 初回表示では動かさない（ページを開いた直後にフォーカスが飛ぶのを避ける）。
  React.useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    const heading = headingRef.current?.querySelector("h1");
    if (heading instanceof HTMLElement) {
      heading.setAttribute("tabindex", "-1");
      heading.focus();
    }
  }, [openPolicyId, demoState]);

  if (openPolicy) {
    return (
      <PolicyDetail
        policy={openPolicy}
        onBack={() => setOpenPolicyId(null)}
        headingRef={headingRef}
      />
    );
  }

  return (
    <div className="pb-16">
      <div ref={headingRef}>
        <PageHeader
          title="ご契約のマイページ"
          subtitle={`${INSURED.name} さま・お客さま番号 ${INSURED.customerNo}`}
        />
      </div>

      <Container size="md" className="pt-4">
        <DemoSwitch value={demoState} onChange={setDemoState} />

        {demoState === "loading" ? (
          <PolicyListSkeleton />
        ) : policies.length === 0 ? (
          <Card className="mt-6">
            <CardContent className="p-6">
              <EmptyState
                icon={<IconFileDescription className="size-8" aria-hidden="true" />}
                title="ご契約が見つかりませんでした"
                description="お客さま番号でお調べしましたが、有効なご契約がありません。お手元の証券番号をご確認のうえ、お問い合わせください。"
              />
            </CardContent>
          </Card>
        ) : (
          <PolicyList
            policies={policies}
            onOpen={(policy) => setOpenPolicyId(policy.id)}
          />
        )}
      </Container>
    </div>
  );
}

function DemoSwitch({
  value,
  onChange,
}: {
  value: DemoState;
  onChange: (value: DemoState) => void;
}) {
  return (
    <DocNote heading="表示サンプルの切り替え（この画面はデモです）" variant="note">
      <SegmentedControl
        aria-label="表示サンプルの切り替え"
        size="lg"
        value={value}
        onValueChange={(next) => onChange(next as DemoState)}
        options={[
          { value: "ready", label: "通常" },
          { value: "loading", label: "読み込み中" },
          { value: "empty", label: "契約なし" },
        ]}
      />
    </DocNote>
  );
}

function PolicyListSkeleton() {
  return (
    <div className="mt-6" aria-busy="true" aria-live="polite">
      <p className="flex items-center gap-2 text-sm text-muted-foreground">
        <Spinner size="sm" aria-hidden="true" />
        ご契約を読み込んでいます
      </p>
      <div className="mt-4 grid gap-3 sm:grid-cols-3">
        {[0, 1, 2].map((index) => (
          <Skeleton key={index} className="h-20 w-full rounded-lg" />
        ))}
      </div>
      <div className="mt-6 space-y-3">
        {[0, 1].map((index) => (
          <div key={index} className="rounded-lg border bg-card p-4">
            <Skeleton shape="text" className="h-5 w-2/3" />
            <Skeleton shape="text" className="mt-2 h-4 w-full" />
            <Skeleton shape="text" className="mt-2 h-4 w-1/2" />
          </div>
        ))}
      </div>
    </div>
  );
}

function PolicyList({
  policies,
  onOpen,
}: {
  policies: Policy[];
  onOpen: (policy: Policy) => void;
}) {
  const monthlyTotal = policies.reduce(
    (sum, policy) => sum + policy.monthlyPremium,
    0,
  );
  const nextCharge = policies
    .map((policy) => policy.nextChargeDate)
    .sort()[0];

  return (
    <>
      <div className="mt-6">
        <StatGroup
          cols={{ base: 1, sm: 3 }}
          items={[
            { label: "ご契約の件数", value: `${policies.length}件` },
            {
              label: "毎月の保険料（合計）",
              value: formatCurrency(monthlyTotal),
            },
            {
              label: "次回の引き落とし",
              value: formatJaDate(nextCharge),
              hint: "口座振替",
            },
          ]}
        />
      </div>

      <section className="mt-8" aria-labelledby="policy-list-heading">
        <h2 id="policy-list-heading" className="text-lg font-semibold">
          加入している保険
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          カードをえらぶと、保障の中身と請求の入口がひらきます。
        </p>

        <ul className="mt-3 list-none space-y-3 p-0">
          {policies.map((policy) => (
            <li key={policy.id}>
              <ListCard
                title={policy.productName}
                description={
                  <>
                    <span className="block">証券番号 {policy.policyNo}</span>
                    <span className="block">
                      契約日 {formatJaDate(policy.contractDate)}
                    </span>
                    <span className="block">保険期間 {policy.termLabel}</span>
                  </>
                }
                tags={
                  <>
                    <Badge variant="outline" icon={<IconShieldCheck />}>
                      {policy.productType}
                    </Badge>
                    <Badge variant="success" icon={<IconCircleCheck />}>
                      {policy.status}
                    </Badge>
                  </>
                }
                meta={
                  <span className="tabular-nums">
                    毎月 {formatCurrency(policy.monthlyPremium)}
                  </span>
                }
                onSelect={() => onOpen(policy)}
              />
            </li>
          ))}
        </ul>
      </section>
    </>
  );
}

function PolicyDetail({
  policy,
  onBack,
  headingRef,
}: {
  policy: Policy;
  onBack: () => void;
  headingRef: React.RefObject<HTMLDivElement | null>;
}) {
  return (
    <div className="pb-16">
      <div ref={headingRef}>
        <PageHeader
          title={policy.productName}
          subtitle={`証券番号 ${policy.policyNo}`}
          onBack={onBack}
          backLabel="ご契約の一覧にもどる"
        />
      </div>

      <Container size="md" className="pt-4">
        <Card>
          <CardContent className="p-4">
            <MetadataList
              wrap
              items={[
                { label: "ご契約の状況", value: policy.status },
                {
                  label: "契約日",
                  value: formatJaDate(policy.contractDate),
                },
                { label: "保険期間", value: policy.termLabel },
                {
                  label: "毎月の保険料",
                  value: (
                    <span className="tabular-nums">
                      {formatCurrency(policy.monthlyPremium)}
                    </span>
                  ),
                },
                {
                  label: "次回の引き落とし",
                  value: formatJaDate(policy.nextChargeDate),
                  description: policy.paymentMethod,
                },
              ]}
            />
          </CardContent>
        </Card>

        <Tabs defaultValue="coverage" className="mt-6">
          <TabsList className="w-full">
            <TabsTrigger value="coverage">保障内容</TabsTrigger>
            <TabsTrigger value="claim">請求・給付</TabsTrigger>
            <TabsTrigger value="premium">保険料</TabsTrigger>
            <TabsTrigger value="procedures">お手続き</TabsTrigger>
          </TabsList>

          <TabsContent value="coverage" className="mt-6">
            <CoverageTab policy={policy} />
          </TabsContent>
          <TabsContent value="claim" className="mt-6">
            <ClaimTab policy={policy} />
          </TabsContent>
          <TabsContent value="premium" className="mt-6">
            <PremiumTab policy={policy} />
          </TabsContent>
          <TabsContent value="procedures" className="mt-6">
            <ProceduresTab />
          </TabsContent>
        </Tabs>
      </Container>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Alert,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CheckList,
  EmptyState,
  RadioCard,
  RadioCardGroup,
  Statistic,
  Stepper,
  Timeline,
  formatCurrency,
} from "@gunjo/ui";
import {
  IconCircleCheck,
  IconCircleX,
  IconHeartbeat,
  IconInfoCircle,
} from "@tabler/icons-react";
import { formatJaDate, type Policy } from "./data";

export function ClaimTab({ policy }: { policy: Policy }) {
  const [situationId, setSituationId] = React.useState<string | null>(null);

  React.useEffect(() => {
    setSituationId(null);
  }, [policy]);

  const situation = policy.situations.find((item) => item.id === situationId);
  const eligibleCount = situation?.results.filter((r) => r.eligible).length ?? 0;

  const totalPaid = policy.paidBenefits.reduce(
    (sum, benefit) => sum + benefit.amount,
    0,
  );

  return (
    <div className="space-y-8">
      <section aria-labelledby="claim-heading">
        <h2 id="claim-heading" className="text-lg font-semibold">
          給付金の請求
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          あてはまる状況をえらぶと、この契約で請求できるものが分かります。
        </p>

        <div className="mt-3">
          <RadioCardGroup
            aria-label="どんな状況ですか"
            value={situationId ?? undefined}
            onValueChange={setSituationId}
            className="grid gap-2 sm:grid-cols-2"
          >
            {policy.situations.map((item) => (
              <RadioCard
                key={item.id}
                value={item.id}
                title={item.label}
                description={item.description}
              />
            ))}
          </RadioCardGroup>
        </div>

        {situation ? (
          <Card className="mt-4">
            <CardHeader className="pb-3">
              <CardTitle as="h3" className="text-base">
                「{situation.label}」ときに請求できるもの
              </CardTitle>
              <CardDescription>
                {eligibleCount > 0
                  ? `この契約では ${eligibleCount}件 が対象になりえます。最終的な判断は、ご提出いただく書類でおこないます。`
                  : "この契約では対象になるものがありません。ほかのご契約をご確認ください。"}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <CheckList
                items={situation.results.map((result, index) => ({
                  id: `${situation.id}-${index}`,
                  label: result.coverageName,
                  description: result.note,
                  trailing: (
                    <span className="flex flex-col items-end gap-1 text-right">
                      <Badge
                        variant={result.eligible ? "success" : "secondary"}
                        icon={
                          result.eligible ? <IconCircleCheck /> : <IconCircleX />
                        }
                      >
                        {result.eligible ? "対象" : "対象外"}
                      </Badge>
                      <span className="text-sm font-semibold tabular-nums">
                        {result.amount}
                      </span>
                    </span>
                  ),
                }))}
              />

              <Alert
                variant="info"
                icon={<IconInfoCircle />}
                title="請求のながれ"
                description="オンラインで申し込むと、必要な書類の一覧が出ます。書類がそろってから5営業日ほどでお振り込みします。"
              />

              <Stepper
                steps={[
                  { label: "状況をえらぶ", state: "completed" },
                  { label: "書類を用意", state: "current" },
                  { label: "申し込む", state: "upcoming" },
                  { label: "お振込", state: "upcoming" },
                ]}
              />

              <Button className="w-full" disabled={eligibleCount === 0}>
                この内容で請求に進む
              </Button>
            </CardContent>
          </Card>
        ) : (
          <Card className="mt-4">
            <CardContent className="p-4">
              <EmptyState
                headingLevel={3}
                icon={<IconHeartbeat className="size-8" aria-hidden="true" />}
                title="状況をえらんでください"
                description="えらぶと、この契約のどの保障から、いくら請求できるかが表示されます。"
              />
            </CardContent>
          </Card>
        )}
      </section>

      <section aria-labelledby="paid-heading">
        <h2 id="paid-heading" className="text-lg font-semibold">
          これまでの給付
        </h2>

        {policy.paidBenefits.length === 0 ? (
          <Card className="mt-3">
            <CardContent className="p-4">
              <EmptyState
                headingLevel={3}
                title="まだ受け取った給付金はありません"
                description="給付金をお支払いすると、ここに履歴が残ります。"
              />
            </CardContent>
          </Card>
        ) : (
          <Card className="mt-3">
            <CardHeader className="pb-3">
              <Statistic
                label="これまでに受け取った合計"
                value={formatCurrency(totalPaid)}
                hint={`${policy.paidBenefits.length}件`}
              />
            </CardHeader>
            <CardContent>
              <Timeline
                items={policy.paidBenefits.map((benefit) => ({
                  time: formatJaDate(benefit.date),
                  title: (
                    <span className="flex flex-wrap items-baseline gap-x-2">
                      <span>{benefit.kind}</span>
                      <span className="font-semibold tabular-nums">
                        {formatCurrency(benefit.amount)}
                      </span>
                    </span>
                  ),
                  description: (
                    <span className="flex flex-wrap items-center gap-2">
                      <span>{benefit.reason}</span>
                      <Badge
                        variant={
                          benefit.status === "支払済" ? "success" : "warning"
                        }
                        size="sm"
                      >
                        {benefit.status}
                      </Badge>
                    </span>
                  ),
                  variant: benefit.status === "支払済" ? "success" : "active",
                }))}
              />
            </CardContent>
          </Card>
        )}
      </section>
    </div>
  );
}

"use client";

/**
 * CoverageSpanChart — 年齢を横軸にして、主契約と各特約の「いつまで保障があるか」を並べる図。
 *
 * @gunjo/ui には行×時間のタイムラインとして Gantt があるが、
 * 日単位（resolution: "day" | "hour"）しか無く、数十年のスパンは描けない。
 * SegmentTimelineCard は数値軸を持つが、セグメントを 1 本のレーンに重ねて置くため、
 * 「同じ日に始まって満了年齢だけが違う」重なりあう保障を並べて見せられない。
 * そのため年単位・複数行のスパン図はここで自前で組んでいる。
 *
 * 図そのものは装飾（aria-hidden）で、同じ内容を必ずテキストでも書いている。
 */

import { Badge } from "@gunjo/ui";
import type { CoverageNode } from "./data";
import { yearsUntil } from "./data";

function ageAt(dateISO: string, birthdayISO: string): number {
  const date = new Date(`${dateISO}T00:00:00`);
  const birthday = new Date(`${birthdayISO}T00:00:00`);
  let age = date.getFullYear() - birthday.getFullYear();
  const beforeBirthday =
    date.getMonth() < birthday.getMonth() ||
    (date.getMonth() === birthday.getMonth() && date.getDate() < birthday.getDate());
  if (beforeBirthday) age -= 1;
  return age;
}

const LIFETIME_AXIS_MAX = 100;

export function CoverageSpanChart({
  coverages,
  currentAge,
  birthday,
}: {
  coverages: CoverageNode[];
  currentAge: number;
  birthday: string;
}) {
  const rows = coverages.map((coverage) => ({
    coverage,
    startAge: ageAt(coverage.startDate, birthday),
    endAge: coverage.expiryAge,
    remainingYears: coverage.expiryDate ? yearsUntil(coverage.expiryDate) : null,
  }));

  const axisMin = Math.min(...rows.map((row) => row.startAge), currentAge) - 2;
  const hasLifetime = rows.some((row) => row.endAge === null);
  const axisMax = hasLifetime
    ? LIFETIME_AXIS_MAX
    : Math.max(...rows.map((row) => row.endAge ?? 0)) + 3;
  const span = Math.max(axisMax - axisMin, 1);
  const pct = (age: number) => ((age - axisMin) / span) * 100;

  return (
    <div>
      <div className="space-y-4">
        {rows.map(({ coverage, startAge, endAge, remainingYears }) => {
          const left = pct(startAge);
          const right = pct(endAge ?? axisMax);
          const isLifetime = endAge === null;

          return (
            <div key={coverage.id}>
              <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
                <span className="text-sm font-medium">{coverage.name}</span>
                <span className="text-sm text-muted-foreground tabular-nums">
                  {isLifetime
                    ? `${startAge}歳から 終身`
                    : `${startAge}歳〜${endAge}歳（あと約${remainingYears}年）`}
                </span>
              </div>

              <div
                aria-hidden="true"
                className="relative mt-1.5 h-3 w-full overflow-hidden rounded-full bg-muted"
              >
                <div
                  className={
                    isLifetime
                      ? "absolute inset-y-0 rounded-full bg-primary/80"
                      : "absolute inset-y-0 rounded-full bg-primary/50"
                  }
                  style={{
                    left: `${left}%`,
                    width: `${Math.max(right - left, 1)}%`,
                  }}
                />
                <div
                  className="absolute inset-y-0 w-0.5 bg-foreground"
                  style={{ left: `${pct(currentAge)}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>

      <div
        aria-hidden="true"
        className="relative mt-2 h-5 text-xs text-muted-foreground tabular-nums"
      >
        <span className="absolute left-0">{axisMin}歳</span>
        <span
          className="absolute -translate-x-1/2 font-medium text-foreground"
          style={{ left: `${pct(currentAge)}%` }}
        >
          {currentAge}歳
        </span>
        <span className="absolute right-0">
          {hasLifetime ? "終身" : `${axisMax}歳`}
        </span>
      </div>

      <p className="mt-3 text-sm text-muted-foreground">
        縦線が、いまのご年齢（{currentAge}歳）です。
      </p>

      <div className="mt-2 flex flex-wrap gap-2">
        <Badge variant="outline">お誕生日 {birthday.replace(/-/g, "/")}</Badge>
        <Badge variant="outline">満了の3か月前にご案内をお送りします</Badge>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Alert,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  DistributionBar,
  NumberInput,
  PersonCell,
  Separator,
  Sheet,
  SheetBody,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@gunjo/ui";
import { IconInfoCircle, IconUserEdit } from "@tabler/icons-react";
import { CoverageSpanChart } from "./CoverageSpanChart";
import { CoverageTree } from "./CoverageTree";
import { INSURED, type Beneficiary, type Policy } from "./data";

export function CoverageTab({ policy }: { policy: Policy }) {
  const [beneficiaries, setBeneficiaries] = React.useState<Beneficiary[]>(
    policy.beneficiaries,
  );
  const [draft, setDraft] = React.useState<Beneficiary[]>(policy.beneficiaries);
  const [sheetOpen, setSheetOpen] = React.useState(false);
  const [applied, setApplied] = React.useState(false);

  React.useEffect(() => {
    setBeneficiaries(policy.beneficiaries);
    setDraft(policy.beneficiaries);
    setApplied(false);
  }, [policy]);

  const draftTotal = draft.reduce((sum, person) => sum + person.share, 0);
  const isValid = draftTotal === 100;

  const openSheet = () => {
    setDraft(beneficiaries);
    setSheetOpen(true);
  };

  const submit = () => {
    setBeneficiaries(draft);
    setApplied(true);
    setSheetOpen(false);
  };

  return (
    <div className="space-y-8">
      <section aria-labelledby="coverage-tree-heading">
        <h2 id="coverage-tree-heading" className="text-lg font-semibold">
          主契約と特約
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          この契約で受け取れるお金の一覧です。特約は主契約に付けている追加の保障です。
        </p>
        <div className="mt-3">
          <CoverageTree coverages={policy.coverages} />
        </div>
      </section>

      <section aria-labelledby="coverage-span-heading">
        <h2 id="coverage-span-heading" className="text-lg font-semibold">
          保障の期間
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          特約は満了する年齢がそれぞれ違います。満了すると、その保障だけが終わります。
        </p>
        <Card className="mt-3">
          <CardContent className="p-4">
            <CoverageSpanChart
              coverages={policy.coverages}
              currentAge={INSURED.age}
              birthday={INSURED.birthday}
            />
          </CardContent>
        </Card>
      </section>

      <section aria-labelledby="beneficiary-heading">
        <h2 id="beneficiary-heading" className="text-lg font-semibold">
          受取人
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          {policy.beneficiaryTargetLabel}です。
        </p>

        {applied ? (
          <Alert
            variant="success"
            className="mt-3"
            icon={<IconInfoCircle />}
            title="受取人の変更を受け付けました"
            description="ご署名いただく書類を1週間ほどでお送りします。書類が届くまでは、これまでの受取人のままです。"
          />
        ) : null}

        <Card className="mt-3">
          <CardHeader className="pb-3">
            <CardTitle as="h3" className="text-base">
              受け取る割合
            </CardTitle>
            <CardDescription>合計 100%</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <DistributionBar
              segments={beneficiaries.map((person) => ({
                label: `${person.name}（${person.relation}）`,
                value: person.share,
              }))}
              formatValue={(value) => `${value}%`}
              totalLabel="受取割合"
            />

            <Separator />

            <ul className="list-none space-y-3 p-0">
              {beneficiaries.map((person) => (
                <li key={person.id}>
                  <PersonCell
                    name={person.name}
                    secondary={person.relation}
                    trailing={
                      <span className="text-sm font-semibold tabular-nums">
                        {person.share}%
                      </span>
                    }
                  />
                </li>
              ))}
            </ul>

            <Button
              variant="outline"
              className="w-full"
              onClick={openSheet}
              aria-haspopup="dialog"
            >
              <IconUserEdit className="size-4" aria-hidden="true" />
              受取人を変更する
            </Button>
            <p className="text-xs text-muted-foreground">
              オンラインでお申し込みいただいたあと、ご署名いただく書類をお送りします。
            </p>
          </CardContent>
        </Card>

        <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
          <SheetContent side="bottom" className="max-h-[90vh] overflow-y-auto">
            <SheetHeader>
              <SheetTitle>受取人の変更を申し込む</SheetTitle>
              <SheetDescription>
                割合の合計が100%になるように入力してください。お申し込みのあと、ご署名いただく書類をお送りします。
              </SheetDescription>
            </SheetHeader>

            <SheetBody className="space-y-4">
              {draft.map((person, index) => (
                <div key={person.id}>
                  <NumberInput
                    label={`${person.name}（${person.relation}）の割合`}
                    description="0〜100の%で入力してください"
                    value={person.share}
                    min={0}
                    max={100}
                    step={5}
                    layout="stepper"
                    onValueChange={(value) =>
                      setDraft((current) =>
                        current.map((item, itemIndex) =>
                          itemIndex === index ? { ...item, share: value } : item,
                        ),
                      )
                    }
                  />
                </div>
              ))}

              <div
                className="flex items-center justify-between rounded-md border px-3 py-2 text-sm"
                aria-live="polite"
              >
                <span>合計</span>
                <span className="font-semibold tabular-nums">{draftTotal}%</span>
              </div>

              {!isValid ? (
                <Alert
                  variant="warning"
                  title="合計が100%になっていません"
                  description={`いまの合計は${draftTotal}%です。100%になるように直してください。`}
                />
              ) : null}
            </SheetBody>

            <SheetFooter>
              <Button variant="outline" onClick={() => setSheetOpen(false)}>
                やめる
              </Button>
              <Button onClick={submit} disabled={!isValid}>
                この内容で申し込む
              </Button>
            </SheetFooter>
          </SheetContent>
        </Sheet>

        <div className="mt-3 flex flex-wrap gap-2">
          <Badge variant="outline">受取人は何人でも指定できます</Badge>
          <Badge variant="outline">お手続きに費用はかかりません</Badge>
        </div>
      </section>
    </div>
  );
}

"use client";

/**
 * CoverageTree — 主契約と特約の階層表示。
 *
 * @gunjo/ui に「主契約 → 特約」のような入れ子の内容ブロックを出す部品が無かったため、
 * ここで組んでいる。中身（見出しのチップ、給付額の一覧、満了の表示）は @gunjo/ui の
 * Badge / MetadataList / ExpiryBadge / Separator を使い、
 * 自前なのは「入れ子の器（インデントの罫線＋カード）」だけに絞っている。
 *
 * TreeView を最初に試したが、行のラベルが 1 行 truncate 固定で、
 * 給付額・満了年齢・残り年数を 375px に載せられないため取りやめた（レポート参照）。
 */

import { Badge, ExpiryBadge, MetadataList, Separator } from "@gunjo/ui";
import { IconInfinity, IconShieldCheck } from "@tabler/icons-react";
import type { CoverageNode } from "./data";
import { TODAY, formatJaDate, yearsUntil } from "./data";

const EXPIRY_LABELS = {
  valid: "保障中",
  expiring: "まもなく満了",
  expired: "満了しました",
  missing: "満了なし",
};

function CoverageBlock({ coverage }: { coverage: CoverageNode }) {
  const isMain = coverage.kind === "main";
  const remaining = coverage.expiryDate ? yearsUntil(coverage.expiryDate) : null;

  return (
    <div className="rounded-lg border bg-card p-4">
      <div className="flex flex-wrap items-center gap-2">
        <Badge
          variant={isMain ? "default" : "secondary"}
          icon={isMain ? <IconShieldCheck /> : undefined}
        >
          {isMain ? "主契約" : "特約"}
        </Badge>
        <h4 className="text-base font-semibold">{coverage.name}</h4>
      </div>

      <div className="mt-3">
        <MetadataList
          wrap
          items={coverage.benefits.map((benefit) => ({
            label: benefit.label,
            value: <span className="tabular-nums">{benefit.amount}</span>,
            description: benefit.note,
          }))}
        />
      </div>

      <Separator className="my-3" />

      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 text-sm">
        <span className="text-muted-foreground">保障の期間</span>
        {coverage.expiryDate === null ? (
          <span className="flex items-center gap-2">
            <Badge variant="outline" icon={<IconInfinity />}>
              終身
            </Badge>
            <span className="text-muted-foreground">一生涯つづきます</span>
          </span>
        ) : (
          <span className="flex flex-wrap items-center justify-end gap-x-2 gap-y-1 text-right">
            <span className="font-medium tabular-nums">
              {coverage.expiryAge}歳まで
            </span>
            <ExpiryBadge
              value={coverage.expiryDate}
              today={TODAY}
              warnWithinDays={365}
              labels={EXPIRY_LABELS}
              showDate={false}
              hideRemaining
            />
            <span className="text-muted-foreground tabular-nums">
              あと約{remaining}年（{formatJaDate(coverage.expiryDate)}）
            </span>
          </span>
        )}
      </div>
    </div>
  );
}

export function CoverageTree({ coverages }: { coverages: CoverageNode[] }) {
  const main = coverages.find((coverage) => coverage.kind === "main");
  const riders = coverages.filter((coverage) => coverage.kind === "rider");

  if (!main) return null;

  return (
    <ul className="list-none space-y-3 p-0">
      <li>
        <CoverageBlock coverage={main} />

        {riders.length > 0 ? (
          <>
            <p className="mt-3 pl-3 text-sm text-muted-foreground sm:pl-4">
              この主契約に付けている特約 {riders.length}件
            </p>
            <ul className="mt-2 list-none space-y-3 border-l-2 border-border pl-3 sm:pl-4">
              {riders.map((rider) => (
                <li key={rider.id}>
                  <CoverageBlock coverage={rider} />
                </li>
              ))}
            </ul>
          </>
        ) : null}
      </li>
    </ul>
  );
}

/**
 * 架空の生命保険マイページ用データ。
 * 実在の保険会社・商品・人物とは一切関係ありません。
 */

/** 画面の「今日」。SSR とクライアントで同じ値になるよう固定する。 */
export const TODAY = "2026-08-08";

export interface Insured {
  name: string;
  kana: string;
  birthday: string;
  age: number;
  customerNo: string;
}

export const INSURED: Insured = {
  name: "佐藤 みなと",
  kana: "サトウ ミナト",
  birthday: "1978-05-12",
  age: 48,
  customerNo: "C-0048-2913",
};

/** 主契約 or 特約。`parentId` があれば特約。 */
export interface CoverageNode {
  id: string;
  /** 主契約＝main、特約＝rider */
  kind: "main" | "rider";
  name: string;
  /** 支払われる金額の説明（複数行ありうる） */
  benefits: { label: string; amount: string; note?: string }[];
  /** 終身なら null */
  expiryDate: string | null;
  /** 終身なら null */
  expiryAge: number | null;
  /** 保障の開始（＝契約日と同じことが多い） */
  startDate: string;
  /** 月額保険料（円）。保険料不要の特約は 0 */
  monthlyPremium: number;
  premiumNote?: string;
}

export interface Beneficiary {
  id: string;
  name: string;
  relation: string;
  /** 受取割合（%） */
  share: number;
}

export interface ClaimSituation {
  id: string;
  label: string;
  description: string;
  /** この状況で請求できる（できない）もの */
  results: {
    coverageId: string;
    coverageName: string;
    eligible: boolean;
    amount: string;
    /** 対象外の理由、または注意点 */
    note: string;
  }[];
}

export interface PaidBenefit {
  id: string;
  date: string;
  kind: string;
  reason: string;
  amount: number;
  status: "支払済" | "審査中";
}

export interface PaymentRecord {
  id: string;
  /** 引き落とし月（YYYY-MM） */
  month: string;
  date: string;
  amount: number;
  method: string;
  status: "領収" | "手続き中";
}

export interface Procedure {
  id: string;
  name: string;
  description: string;
  /** online = ネットだけで完結 / documents = 書類のやりとりが必要 / hybrid = ネット申込＋書類 */
  channel: "online" | "documents" | "hybrid";
  lead: string;
}

export interface CertificateDoc {
  id: string;
  year: string;
  title: string;
  description: string;
  meta: string;
  isNew?: boolean;
}

export interface Policy {
  id: string;
  productName: string;
  productType: "終身" | "定期";
  policyNo: string;
  contractDate: string;
  /** 「終身」または「2019年9月1日 〜 2039年9月1日（20年）」 */
  termLabel: string;
  termEndDate: string | null;
  termEndAge: number | null;
  monthlyPremium: number;
  paymentMethod: string;
  paymentNote: string;
  nextChargeDate: string;
  status: "有効" | "払込猶予中";
  coverages: CoverageNode[];
  beneficiaryTargetLabel: string;
  beneficiaries: Beneficiary[];
  situations: ClaimSituation[];
  paidBenefits: PaidBenefit[];
  payments: PaymentRecord[];
}

