    "2025-09",
    "2025-10",
    "2025-11",
    "2025-12",
    "2026-01",
    "2026-02",
    "2026-03",
    "2026-04",
    "2026-05",
    "2026-06",
    "2026-07",
    "2026-08",
  ];
  return months
    .map((month, index) => {
      const isCurrent = index === months.length - 1;
      return {
        id: `pay-${month}`,
        month,
        date: `${month}-27`,
        amount,
        method,
        status: isCurrent ? ("手続き中" as const) : ("領収" as const),
      };
    })
    .reverse();
}

