/** 満了日までのおおよその残り年数。 */
export function yearsUntil(dateISO: string, todayISO: string = TODAY): number {
  const end = new Date(`${dateISO}T00:00:00`);
  const today = new Date(`${todayISO}T00:00:00`);
  const ms = end.getTime() - today.getTime();
  return Math.max(0, Math.round(ms / (1000 * 60 * 60 * 24 * 365.25)));
}

/** 「2026-08-27」→「2026年8月27日」 */
export function formatJaDate(dateISO: string): string {
  const [y, m, d] = dateISO.split("-");
  return `${y}年${Number(m)}月${Number(d)}日`;
}

/** 「2026-08」→「2026年8月」 */
export function formatJaMonth(monthISO: string): string {
  const [y, m] = monthISO.split("-");
  return `${y}年${Number(m)}月分`;
}

